'use strict';
// A first visit begins with a choice. Shared plans go straight to the calculation.
let journeyKind='growth',wizardActive=false,basicsTouched=false,journeyFresh=false,journeyEditing=false;
function hasStarted(){try{return localStorage.getItem('sv-started')==='1';}catch{return false;}}
function rememberStart(){try{localStorage.setItem('sv-started','1');}catch{}}
function stage(showWizard){wizardActive=showWizard;document.body.dataset.stage=showWizard?'welcome':'workbench';$('welcomeWizard').hidden=!showWizard;$('workbench').hidden=showWizard;$('startAgain').hidden=showWizard;if(!showWizard){rememberStart();render();}window.scrollTo({top:0,behavior:'instant'});}
// Startguiden: et tomt beløpsfelt betyr 0 ("fyll inn tallene du kjenner"). Alder håndteres for seg.
function inputNumber(id){const v=$(id).value;return v.trim()===''?0:parsedNumber(v);}
// Tall som siden selv skriver inn (skyveknapper, startguide, skattevindu), vises med tusenskille som ellers.
function formatInput(value){return groupedNumber(value);}
function prepareJourney(kind){journeyKind=kind;$('chooseGrowth').setAttribute('aria-pressed',kind==='growth');$('chooseGoal').setAttribute('aria-pressed',kind==='goal');$('journeyForm').hidden=false;$('onboardGoalLabel').hidden=kind!=='goal';$('journeyTitle').textContent=kind==='goal'?'Hva vil du spare til?':'Hva er utgangspunktet ditt?';$('beginJourney').textContent=journeyEditing?'Oppdater planen':kind==='goal'?'Se veien til målet ↗':'Vis spareplanen min ↗';$('exampleJourney').hidden=journeyEditing;if($('journeyFreshNote'))$('journeyFreshNote').hidden=!journeyFresh;
 // «Start på nytt» begynner fra standardverdiene, ikke fra planen som står. Planen endres først når brukeren går videre.
 const goal=kind==='goal',src=journeyFresh?E.defaults:s;$('onboardAge').value=src.ageKnown?formatInput(src.userAge):'';$('onboardStart').value=formatInput(goal?src.dreamStart:src.start);$('onboardMonthly').value=formatInput(goal?src.dreamMonthly:src.monthly);$('onboardYears').value=formatInput(goal?src.dreamYears:src.years);$('onboardGoal').value=formatInput(src.dreamCost);$('onboardUntil67').checked=src.until67||(!src.ageKnown&&kind==='growth');$('closeJourney').hidden=!hasStarted();$('journeyError').hidden=true;updateHorizon(false);
}
function updateHorizon(auto){const raw=$('onboardAge').value.trim(),age=inputNumber('onboardAge'),known=raw!==''&&Number.isFinite(age)&&age>=0;$('until67Label').hidden=!known;if(auto&&known&&$('onboardUntil67').checked)$('onboardYears').value=formatInput(Math.max(0,67-age));const years=inputNumber('onboardYears');if(!known){$('journeyHorizon').textContent='Alder er valgfritt. Du kan bruke kalkulatoren uten å oppgi den.';return;}if(!Number.isFinite(years)||years<0){$('journeyHorizon').textContent='Velg hvor mange år du vil spare.';return;}$('journeyHorizon').textContent=`Om ${dec.format(years)} år er du ${dec.format(age+years)}, rundt ${new Date().getFullYear()+Math.round(years)}.`+($('onboardUntil67').checked?' 67 år er bare et startforslag, og kan endres.':'');}
$('chooseGrowth').onclick=()=>{prepareJourney('growth');$('journeyForm').scrollIntoView({behavior:'smooth',block:'nearest'});};$('chooseGoal').onclick=()=>{prepareJourney('goal');$('journeyForm').scrollIntoView({behavior:'smooth',block:'nearest'});};
$('onboardAge').oninput=()=>updateHorizon(true);$('onboardUntil67').onchange=()=>updateHorizon(true);$('onboardYears').oninput=()=>{$('onboardUntil67').checked=false;updateHorizon(false);};
// Nullstiller hele planen (også skjulte valg som børsfall, ekstrainnskudd og spareform) når brukeren går videre fra «Start på nytt».
// «Tilbake til planen» endrer ingenting. Endringen kan angres.
function freshPlan(){if(!journeyFresh)return;journeyFresh=false;undoState={state:{...s},mode,view:{...view}};Object.assign(s,{...E.defaults});view={showBank:false,showRange:false,showGoal:false,both:false};selectedPlans.clear();basicsTouched=false;history.replaceState(null,'',location.pathname);$('undoText').textContent='Planen er nullstilt.';$('undoBar').hidden=false;}
$('startAgain').onclick=()=>{journeyEditing=false;journeyFresh=true;stage(true);prepareJourney(s.activePage==='dreams'?'goal':'growth');};$('closeJourney').onclick=()=>{journeyFresh=false;journeyEditing=false;stage(false);};
function editStartChoices(){journeyEditing=true;journeyFresh=false;stage(true);prepareJourney(s.activePage==='dreams'?'goal':'growth');}
function ageGroupFor(age){if(age<18)return 'all';if(age<25)return '18-24';if(age<30)return '25-29';if(age<35)return '30-34';if(age<40)return '35-39';if(age<45)return '40-44';if(age<50)return '45-49';if(age<55)return '50-54';if(age<67)return '55-66';return '67+';}
$('journeyForm').onsubmit=event=>{event.preventDefault();try{const start=inputNumber('onboardStart'),monthly=inputNumber('onboardMonthly'),years=inputNumber('onboardYears'),age=inputNumber('onboardAge'),known=$('onboardAge').value.trim()!=='';if([start,monthly,years,...(known?[age]:[])].some(x=>!Number.isFinite(x)||x<0))throw Error('Bruk tall fra 0 og oppover. Du kan skrive komma i desimaltall.');if(years>100)throw Error('Sparetid kan være opptil 100 år.');if(known&&age>120)throw Error('Alder må være mellom 0 og 120 år.');if(Math.round(years*12)<1)throw Error(known&&age>=67&&$('onboardUntil67')?.checked?'Du er 67 år eller eldre, så «til 67 år» gir ingen sparetid. Skriv inn hvor mange år du vil spare.':'Sparetiden må være minst én måned. Med 0 år blir det ingen innskudd å regne på.');const goal=journeyKind==='goal',amount=inputNumber('onboardGoal');if(goal&&(!Number.isFinite(amount)||amount<0||Math.round(years*12)<1))throw Error('Velg et mål fra 0 kr og en periode på minst én måned.');
 if(journeyFresh)freshPlan();else undoState={state:{...s},mode,view:{...view}};
 Object.assign(s,{userAge:known?age:0,ageKnown:known,until67:known&&$('onboardUntil67').checked,ageGroup:known?ageGroupFor(age):'all',activePage:goal?'dreams':'calculator'});
 if(goal)Object.assign(s,{dreamStart:start,dreamMonthly:monthly,dreamYears:years,dreamCost:amount});else Object.assign(s,{start,monthly,years});
 if(journeyEditing){$('undoText').textContent='Startvalgene er oppdatert.';$('undoBar').hidden=false;}else{mode='explore';setLevel('simple');}journeyEditing=false;fill();stage(false);
 }catch(error){$('journeyError').textContent=error.message;$('journeyError').hidden=false;for(const id of ['onboardStart','onboardMonthly','onboardYears','onboardAge','onboardGoal']){const v=inputNumber(id),limit=id==='onboardYears'?100:id==='onboardAge'?120:Infinity,empty=$(id).value.trim()==='';$(id).setAttribute('aria-invalid',String(!empty&&(!Number.isFinite(v)||v<0||v>limit)));}$('journeyError').scrollIntoView({block:'nearest'});}};
$('exampleJourney').onclick=()=>{freshPlan();fill();setLevel('simple');s.activePage=journeyKind==='goal'?'dreams':'calculator';stage(false);};
// Skyveknapper er snarveier, aldri grenser. Skrivefeltet er alltid den gjeldende verdien.
const SLIDER_SPECS={start:[0,1000000,1000],monthly:[0,20000,100],years:[0.5,50,.5],rate:[0,15,.1],spread:[0,5,.1],dreamStart:[0,500000,1000],dreamMonthly:[0,20000,100],dreamYears:[0.5,30,.5],dreamCost:[0,1000000,1000],annualWithdraw:[0,600000,1000],withdrawPercent:[0,10,.1]};
// Alle skyveknapper har faste, moderate grenser. Skrivefeltet kan ha høyere gyldige verdier.
function toggleDescribedBy(el,id,on){const ids=(el.getAttribute('aria-describedby')||'').split(' ').filter(x=>x&&x!==id);if(on)ids.push(id);ids.length?el.setAttribute('aria-describedby',ids.join(' ')):el.removeAttribute('aria-describedby');}
for(const [id,[min,max,step]]of Object.entries(SLIDER_SPECS)){const field=$(id);if(!field)continue;const label=field.closest('label'),wrap=document.createElement('div');wrap.className='range-control';const range=document.createElement('input');range.type='range';range.id=id+'Slider';range.min=min;range.max=max;range.step=step;range.setAttribute('aria-label','Juster '+(label.querySelector('.field-label')?.textContent||id).toLowerCase());range.dataset.field=id;
 // Forklaring og bevisst handling når skrivefeltet har en verdi utenfor skyveknappens område.
 const note=document.createElement('p');note.className='range-note';note.id=id+'SliderNote';note.hidden=true;const text=document.createElement('span');const unlock=document.createElement('button');unlock.type='button';unlock.className='text-link';unlock.id=id+'SliderUnlock';note.append(text,' ',unlock);
 unlock.addEventListener('click',e=>{e.preventDefault();range.dataset.unlockedFor=String(s[id]);syncSliders();range.focus();});
 wrap.append(range,note);field.closest('.fieldbox').after(wrap);range.addEventListener('input',()=>{field.value=formatInput(Number(range.value));if(id==='years'||id==='dreamYears')s.until67=false;delete range.dataset.unlockedFor;typingRender=true;read();render();typingRender=false;});}
function syncSliders(){for(const range of document.querySelectorAll('input[type=range][data-field]')){
 const id=range.dataset.field,value=s[id],field=$(id);if(id===pendingKey()){const n=$(id+'SliderNote');if(n){n.hidden=true;toggleDescribedBy(field,n.id,false);}continue;}const valid=Number.isFinite(value)&&E.fieldError(id,value)===null;
 const min=Number(range.min),max=Number(range.max),outside=!Number.isFinite(value)||value<min||value>max,unlocked=outside&&range.dataset.unlockedFor===String(value);
 if(!outside)delete range.dataset.unlockedFor;
 if(Number.isFinite(value))range.value=Math.min(max,Math.max(min,value));
 range.disabled=outside&&!unlocked;
 const unit=field?.closest('label')?.querySelector('.unit')?.textContent||'',shown=Number.isFinite(value)?dec.format(value)+(unit?' '+unit:''):'ugyldig';
 range.setAttribute('aria-valuetext',dec.format(Number(range.value))+(outside?' (skrivefeltet: '+shown+')':''));
 const note=$(id+'SliderNote');if(!note)continue;note.hidden=!outside;if(field)toggleDescribedBy(field,note.id,outside);if(!outside)continue;
 const [text,button]=[note.firstChild,note.querySelector('button')];
 const range_=(min===0&&!(value<min)?'til ':'fra '+dec.format(min)+' til ')+dec.format(max)+(unit?' '+unit:'');
 if(unlocked){text.textContent='Flytter du skyveknappen, erstattes '+shown+'.';button.hidden=true;}
 else{button.hidden=false;button.textContent='bruk skyveknappen';text.textContent=valid?'Skyveknappen går '+range_+'. Beløpet ditt beholdes.':'Tallet er ugyldig. Rett det, eller';if(valid)button.textContent='Bruk skyveknappen likevel';}
}}
for(const id of ['years','dreamYears'])$(id).addEventListener('input',()=>{s.until67=false;});
$('stress').addEventListener('input',()=>{s.riskChosen=true;});
// Move the spread control into the chart so its meaning is visible where it matters.
$('fanSpreadField').append($('spread').closest('label'));
function compactHelp(title,body){$('helpTitle').textContent=title;$('helpBody').innerHTML=body;$('helpDialog').showModal();}
$('fanHelp').onclick=e=>{e.preventDefault();if(s.savingsType==='index'){compactHelp('Utfallsrom for indeksfond',`<p>Båndet viser et 95 % utfallsrom etter Finans Norges standard for avkastningsprognoser: ${dec.format(Assumptions.index.realRate)} % forventet realavkastning og ${dec.format(Assumptions.index.sigma)} % årlig svingning for aksjer.</p><p>Hvert innskudd får sin egen usikkerhet ut fra hvor lenge pengene står. På kort sikt kan snittavkastningen bli negativ. Over mange år jevner svingningene seg mer ut, men beløpet i kroner kan fortsatt variere mye.</p><p>Dette er en modell, ikke en garanti. Virkeligheten kan havne utenfor båndet.</p>`);return;}compactHelp('Tre måter sparingen kan utvikle seg på','<p>Midtlinjen bruker veksten du har valgt. De andre linjene viser hva lavere og høyere vekst ville betydd, med like innskudd og like kostnader.</p><p>Med 5 % vekst og 2 prosentpoeng forskjell bruker vi 3 %, 5 % og 7 %. Avstanden vokser med tiden på grunn av rentes rente.</p><p>Dette er tre regneeksempler. Båndet viser ikke sannsynligheter, og faktisk verdi kan havne både under og over det.</p>');};
$('logHelp').onclick=e=>{e.preventDefault();compactHelp('Like prosentsteg i grafen','<p>Vanlig visning gir like mye plass til like mange kroner. 100 000 kr ekstra ser like stort ut uansett utgangspunkt.</p><p>Med dette valget blir like store prosentvise endringer like høye. Det gjør en svært lang periode eller store beløpsforskjeller lettere å se. Selve beregningen er den samme.</p><p>Dette kalles en logaritmisk skala.</p>');};
function fanSummary(){{const box=$('showRange'),label=box.closest('label'),text=s.savingsType==='index'?'Vis utfallsrom (95 %)':'Vis lavere og høyere vekst',node=[...label.childNodes].find(n=>n.nodeType===3&&n.textContent.trim());if(node&&node.textContent.trim()!==text)node.textContent=' '+text+' ';box.setAttribute('aria-label',text);}const visible=view.showRange&&!(view.both&&!s.real)&&rows.length&&$('error').hidden;$('fanSummary').hidden=!visible;$('fanTuning').hidden=!view.showRange;if(!visible)return;const r=rows.at(-1),idx=s.savingsType==='index';$('fanTuning').hidden=idx||!view.showRange;$('fanSummary').innerHTML=(idx?[['low','Nedre del av utfallsrommet','bear','2,5 % av modellens utfall er lavere'],['v','Din antakelse','base',`${dec.format(s.rate)} % før kostnader`],['high','Øvre del av utfallsrommet','bull','2,5 % av modellens utfall er høyere']]:[['low','Lavere vekst','bear',`${dec.format(s.rate-s.spread)} % før kostnader`],['v','Din antakelse','base',`${dec.format(s.rate)} % før kostnader`],['high','Høyere vekst','bull',`${dec.format(s.rate+s.spread)} % før kostnader`]]).map(([key,name,cls,sub])=>`<div class="fan-outcome ${cls}"><span>${name}</span><strong>${money(r[key])}</strong><small>${sub}${s.real?' · dagens kroner':''}</small></div>`).join('');$('fanSpreadLabel').textContent=`${dec.format(s.spread)} prosentpoeng lavere og høyere`;}
const previousChart=chart;chart=function(){previousChart();fanSummary();const both=view.both&&!s.real;if(view.showRange&&!both&&s.savingsType==='index'){$('chartNote').textContent=`Båndet er et 95 % utfallsrom etter Finans Norges prognosemodell for aksjer (${dec.format(Assumptions.index.sigma)} % årlig svingning). Kort sparetid gir større usikkerhet. Ikke en garanti. Alt er før skatt.`;const key=$('chartLegend').querySelector('.range-key');if(key)key.lastChild.textContent='95 % utfallsrom (modell)';}else if(view.showRange&&!both&&level==='simple')$('chartNote').textContent='Tre regneeksempler før skatt, ikke sannsynligheter. Faktisk verdi kan havne utenfor båndet.';};
// A clear gross result remains visible alongside an optional, separately labelled tax estimate.
function setTaxFields(){const ask=$('taxModel').value==='ask';$('askTaxFields').hidden=!ask;$('shareTaxFields').hidden=ask;$('taxFreeCapital').required=ask;}
$('openTax').onclick=()=>{for(const key of ['taxModel','taxFreeCapital','taxShield','taxRate','taxableShare'])$(key).value=typeof s[key]==='number'?formatInput(s[key]):s[key];if(!s.taxEnabled&&s.taxFreeCapital===0)$('taxFreeCapital').value='';$('taxError').hidden=true;setTaxFields();$('taxDialog').showModal();};
$('taxModel').onchange=setTaxFields;$('closeTax').onclick=()=>$('taxDialog').close();
$('usePlanDeposits').onclick=()=>{$('taxFreeCapital').value=formatInput(nominalPaid(endYear(s)));};
$('taxForm').onsubmit=event=>{event.preventDefault();try{const patch={taxModel:$('taxModel').value,taxFreeCapital:inputNumber('taxFreeCapital'),taxShield:inputNumber('taxShield'),taxRate:inputNumber('taxRate'),taxableShare:inputNumber('taxableShare'),taxEnabled:true};TaxEstimate.validate(patch);changePlan(patch,'Skatteanslaget for uttak er slått på.');$('taxDialog').close();}catch(error){$('taxError').textContent=error.message;$('taxError').hidden=false;}};
$('disableTax').onclick=()=>{s.taxEnabled=false;$('taxDialog').close();render();};
function taxMarkup(r){const first=TaxEstimate.at(s,r,1),last=TaxEstimate.at(s,r,r.n);return `<section class="net-estimate"><div class="panel-title"><h3>Anslag etter avsatt skatt</h3><button class="text" id="editTaxEstimate" type="button">Endre</button></div><div class="net-figures"><div><span>Ordinært uttak første år</span><strong>${money(first.regularNet)}</strong><small>${money(first.regularNet/12)} per måned</small></div><div><span>Samlet tilgjengelig på ${r.n} år</span><strong>${money(last.totalNet)}</strong><small>Anslått skatt: ${money(last.totalTax)}</small></div></div><p class="hint">${s.taxModel==='ask'?`Forenklet ASK: ${money(s.taxFreeCapital)} innskudd og ${money(s.taxShield)} kjent skjerming før gevinst skattlegges.`:`${dec.format(s.taxableShare)} % av hvert uttak er antatt skattepliktig.`} Sats: ${dec.format(s.taxRate)} %. Fremtidig skatt og skjerming er usikkert.</p><p class="hint">Skatten settes av fra samme uttak. Saldoen og beregnet varighet er fortsatt før skatt.</p></section>`;}
function refreshTax(){const target=$('taxEstimate');target.hidden=!s.taxEnabled;if(!s.taxEnabled){$('openTax').textContent='Anslå etter skatt ↗';return;}$('openTax').textContent='Endre skatteanslaget ↗';try{const r=E.withdrawal(s,E.value(s,endYear(s)));target.innerHTML=taxMarkup(r);$('editTaxEstimate').onclick=()=>$('openTax').click();const head=$('withdrawTable').querySelector('thead tr');if(head){for(const title of ['Ordinært uttak etter avsatt skatt','Skatt inkl. ekstrauttak']){const th=document.createElement('th');th.textContent=title;head.append(th);}const trs=[...$('withdrawTable').querySelectorAll('tbody tr')];trs.forEach((tr,i)=>{const point=TaxEstimate.at(s,r,r.points[i].year);for(const value of [point.regularNet,point.tax]){const td=document.createElement('td');td.textContent=money(value);tr.append(td);}});}}catch(error){target.textContent='Skatteanslaget kunne ikke beregnes: '+error.message;}}
// Linjen under overskriften viser bare alder og spareperiode. Risikovalget gjentas ikke her: det endrer ikke
// beregningen, og et ekko uten forklaring ser ut som en vurdering fra siden. Valget brukes i sparemål og veileder.
function currentHorizon(){const known=s.ageKnown&&Number.isFinite(s.userAge)&&s.userAge>=0,years=s.activePage==='dreams'?s.dreamYears:s.years;$('planContext').hidden=!known;if(!known)return;const end=s.userAge+years;$('planContext').innerHTML=`Du er ${dec.format(s.userAge)} år. Spareperioden går til omtrent ${dec.format(end)} år (${new Date().getFullYear()+Math.round(years)}). `+`<button id="editHorizon" class="text" type="button">Endre startvalg</button>`;$('editHorizon').onclick=editStartChoices;}
const previousRender=render;render=function(){previousRender();syncSliders();currentHorizon();refreshTax();updateStartNote();};
const previousSetPage=setPage;setPage=function(page){previousSetPage(page);currentHorizon();};
const previousSetLevel=setLevel;setLevel=function(value){previousSetLevel(value);syncSliders();};
// Export matrices contain numbers, not formatted currency strings.
function savingsMatrix(){const useRange=view.showRange;const headings=['År med sparing',...(s.ageKnown?['Alder, omtrent']:[]),'Saldo før skatt, kr','Innskudd, kr','Saldo i dagens kroner, kr',...(useRange?['Lavere vekst før skatt, kr','Høyere vekst før skatt, kr']:[])];return [headings,...rows.map(p=>[p.t,...(s.ageKnown?[s.userAge+p.t]:[]),E.value(s,p.t),nominalPaid(p.t),E.value(s,p.t)/inflation(p.t),...(useRange?[E.value(s,p.t,s.rate-s.spread),E.value(s,p.t,s.rate+s.spread)]:[])])];}
function withdrawalMatrix(){const r=E.withdrawal(s,E.value(s,endYear(s)));return [['Uttaksår','Ordinært uttak før skatt, kr','Ekstrauttak før skatt, kr','Saldo etter uttak før skatt, kr','Samlet tatt ut før skatt, kr',...(s.taxEnabled?['Ordinært uttak etter avsatt skatt, kr','Anslått skatt dette året, kr','Samlet etter avsatt skatt, kr']:[])],...r.points.map(p=>{const t=s.taxEnabled?TaxEstimate.at(s,r,p.year):null;return [p.year,p.actual,p.extra||0,p.balance,p.total,...(t?[t.regularNet,t.tax,t.totalNet]:[])];})];}
function goalMatrix(){return [['Alternativ','Årlig avkastning etter kostnad, prosent','Mål ved kjøp, kr','Nødvendig sparing per måned, kr','Sluttbeløp med ditt budsjett, kr','Stresstest, kr'],...E.dreamPlans(s).map((p,i)=>[['Lavere risiko','Moderat risiko','Høyere risiko'][i],p.rate,p.goal,p.required,p.end,p.stressed])];}
const EXPORT_LABELS={savingsType:'Spareform (bare forklaringer)',userAge:'Alder',ageKnown:'Alder oppgitt',until67:'Sparing til 67 foreslått',riskChosen:'Risikovalg oppgitt',taxEnabled:'Skatteanslag for uttak på',taxModel:'Modell for skatteanslag',taxFreeCapital:'Skattefrie innskudd ved uttaksstart, kr',taxShield:'Kjent skjerming ved uttaksstart, kr',taxRate:'Skattesats i anslaget, prosent',taxableShare:'Skattepliktig andel i egen modell, prosent'};
function settingsMatrix(){return [['Forutsetning','Verdi'],['Beregnet',new Date().toISOString()],['Spareutvikling','Før skatt'],['Skatteanslag',s.taxEnabled?'Separat, forenklet anslag for uttak':'Ikke aktivert'],...Object.entries(s).filter(([key])=>key!=='withdraw').map(([key,value])=>[EXPORT_LABELS[key]||labelMap[key]?.label||key,typeof value==='boolean'?value?'Ja':'Nei':key==='savingsType'?({checking:'Brukskonto',savings:'Sparekonto',index:'Indeksfond'}[value]||'Ikke valgt'):value]),['Visningsnivå',level],['Lavere/høyere vekst vises',view.showRange?'Ja':'Nei'],['Merknad','Ingen nye skjermingsfradrag, formuesskatt, IPS, BSU eller fremtidige skattesatser er modellert. Grafens utfallsbånd viser ikke sannsynlighet.']];}
function activeMatrix(){return s.activePage==='withdrawals'?withdrawalMatrix():s.activePage==='dreams'?goalMatrix():savingsMatrix();}
function exportSheets(){const problem=planProblem();if(problem)throw problem;const sheets=[{name:'Forutsetninger',rows:settingsMatrix()}];sheets.push({name:'Sparing',rows:savingsMatrix()});try{sheets.push({name:'Uttak',rows:withdrawalMatrix()});}catch(error){if(s.activePage==='withdrawals')throw error;}try{sheets.push({name:'Sparemål',rows:goalMatrix()});}catch(error){if(s.activePage==='dreams')throw error;}const comparisons=selectedComparisons();if(comparisons.length)sheets.push({name:'Sammenligning',rows:[['Plan','År','Månedssparing, kr','Årlig avkastning, prosent','Årlig kostnad, prosent','Sluttbeløp før skatt, kr','Dagens kroner, kr'],...comparisons.map(c=>[c.name,c.n.years,c.n.monthly,c.n.rate,c.n.fee,E.value(c.n,endYear(c.n)),E.value(c.n,endYear(c.n))/inflation(endYear(c.n),c.n)])]});for(const sheet of sheets)if(sheet.rows.some(row=>row.some(x=>typeof x==='number'&&!Number.isFinite(x))))throw Error('En eksportert verdi overstiger tallområdet. Reduser perioden eller veksten.');return sheets;}
function downloadData(data,type,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.hidden=true;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function guardedExport(fn){try{$('exportError').hidden=true;fn();}catch(error){$('exportError').textContent=error.message;$('exportError').hidden=false;}}
const reportAction=$('reportButton').onclick;
$('reportButton').onclick=()=>{if(blockIfInvalid('Rett feltet før du eksporterer.'))return;$('exportError').hidden=true;$('exportDialog').showModal();};$('closeExport').onclick=()=>$('exportDialog').close();
$('exportPdf').onclick=()=>{$('exportDialog').close();if(blockIfInvalid('Rett feltet før du lager rapporten.'))return;reportAction();};
$('exportXlsx').onclick=()=>guardedExport(()=>downloadData(ExportKit.workbook(exportSheets()),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','spareverksted.xlsx'));
function downloadCsv(){const problem=planProblem();if(problem)throw problem;downloadData(ExportKit.csv(activeMatrix()),'text/csv;charset=utf-8','spareverksted.csv');}
$('exportCsv').onclick=()=>guardedExport(downloadCsv);$('csv').onclick=()=>{if(blockIfInvalid('Rett feltet før du eksporterer.'))return;try{downloadCsv();}catch(error){notice(error.message);}};
$('exportJson').onclick=()=>guardedExport(()=>downloadData(JSON.stringify({format:'spareverksted',version:10,created:new Date().toISOString(),state:{...s},mode,view:{...view},level,tables:exportSheets()},null,2),'application/json;charset=utf-8','spareverksted.json'));
const previousReport=buildReport;buildReport=function(){let html=previousReport();if(s.ageKnown)html=html.replace('</div>',`<p>Alder ved start: ${escapeHTML(dec.format(s.userAge))} år. Alder ved slutten av spareperioden: omtrent ${escapeHTML(dec.format(s.userAge+(s.activePage==='dreams'?s.dreamYears:endYear(s))))} år.</p></div>`);if(s.activePage==='withdrawals'&&s.taxEnabled){const r=E.withdrawal(s,E.value(s,endYear(s)));const tax=taxMarkup(r).replace('<button class="text" id="editTaxEstimate" type="button">Endre</button>','')+'<p class="report-footnote">Skattesatsen er en redigerbar forutsetning. Kilder: Skatteetaten om ASK og aksjeinntekter i 2026. Ingen ny skjerming er fremskrevet.</p>';html=html.replace('<div class="report-block"><h3>Slik kan resultatet forstås</h3>',tax+'<div class="report-block"><h3>Slik kan resultatet forstås</h3>');}return html;};
// Risk tolerance changes explanations, never silently changes the return assumption.
const previousTips=tips;tips=function(needed){previousTips(needed);if(s.riskChosen&&s.stress==='low'){const tip=document.createElement('div');tip.className='tip';tip.innerHTML='<h3>Du ønsker lite uro</h3><p>Prøv lavere vekst i planen og se hva som trengs for å nå målet. Risikoviljen din er ikke brukt til å øke eller senke avkastningen automatisk.</p>';$('tips').prepend(tip);}};
fill();render();
const sharedPlan=hash.has('start')||hash.has('dreamCost')||hash.has('activePage');
// Én samlet, kort forklaring av startverdiene i stedet for merker ved hvert felt. Eksempeltall: beløp og sparetid
// før brukeren har endret dem. Forutsetninger: vekst, prisvekst og kostnad som fortsatt står på startverdiene.
// Delte lenker, startguiden og endringer i feltene regnes som brukerens egne tall. «Nullstill» gir eksempel igjen.
basicsTouched=sharedPlan;
document.addEventListener('input',e=>{const id=e.target.dataset?.field||e.target.id;if(['start','monthly','years'].includes(id)&&!basicsTouched){basicsTouched=true;updateStartNote();}});
$('journeyForm').addEventListener('submit',()=>{basicsTouched=true;updateStartNote();});
$('reset').addEventListener('click',()=>{basicsTouched=false;updateStartNote();});
function updateStartNote(){const n=$('startNote');if(!n)return;const parts=[],A=Assumptions,t=s.savingsType,presetRate=t==='index'?A.indexRate(s.inflation):t?A[t].rate:null,usesPreset=presetRate!==null&&s.rate===presetRate;
 if(!basicsTouched&&['start','monthly','years'].every(k=>s[k]===E.defaults[k]))parts.push('Beløp og tid er eksempeltall.');
 if(usesPreset)parts.push(t==='index'?`Veksten ${dec.format(presetRate)} % er ${dec.format(A.index.realRate)} % forventet realavkastning for aksjer (Finans Norges prognosestandard, februar 2026) pluss prisveksten. Ikke en garanti.`:A[t].note);
 const names={rate:'vekst',inflation:'prisvekst',fee:'kostnad'},left=Object.keys(names).filter(k=>s[k]===E.defaults[k]&&!(k==='rate'&&usesPreset));
 if(left.length){const list=left.map(k=>names[k]),joined=list.length>1?list.slice(0,-1).join(', ')+' og '+list.at(-1):list[0];
  parts.push(`${joined[0].toUpperCase()+joined.slice(1)} er forhåndsutfylt, ikke anbefalt eller beregnet fra svarene dine.`+(!t&&(left.includes('rate')||left.includes('fee'))?' På sparekonto: bruk kontoens rente og 0 % kostnad.':''));}
 const text=parts.join(' ');if(n.textContent!==text)n.textContent=text;n.hidden=!text;}
updateStartNote();stage(!(hasStarted()||sharedPlan));

const previousReportChart=reportChart;reportChart=function(){return previousReportChart()+(view.showRange?'<div class="fan-summary">'+$('fanSummary').innerHTML+'</div>':'');};
$('showRange').setAttribute('aria-label','Vis lavere og høyere vekst');$('log').setAttribute('aria-label','Vis like prosentsteg på aksen');$('spread').closest('label').querySelector('.unit').textContent='%-poeng';
